import{_ as a,o as t,c as r,a5 as i}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"Object Records & Image Evidence","description":"","frontmatter":{"title":"Object Records & Image Evidence","gallery":"archive-reading"},"headers":[],"relativePath":"gallery/archive-reading.md","filePath":"gallery/archive-reading.md","lastUpdated":1789230763000}'),o={name:"gallery/archive-reading.md"};function d(n,e,c,l,s,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="object-records-image-evidence" tabindex="-1">Object Records &amp; Image Evidence <a class="header-anchor" href="#object-records-image-evidence" aria-label="Permalink to &quot;Object Records &amp; Image Evidence&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>One image does not always equal one independent work: it may be a display photograph, historical illustration, another state of the same stone, or a related view created for studying craft. This page gives a basic method for reading gallery records.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Separate the object source from the image source: one answers “what is this?” and the other records who made the image and how it may be reused.</li><li>A year may describe the object, design, or a recutting event; it is not automatically the photograph date.</li><li>Cards marked “Archive relation” may share an object or image. Read them as linked records, not duplicate independent works.</li><li>Weight, history, and institutional custody are archive facts; they do not replace a modern identification, grading report, or valuation.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Detail</th><th>Note</th></tr></thead><tbody><tr><td>Wittelsbach</td><td>before / after recut</td><td>one stone, linked archive states</td></tr><tr><td>Display photograph</td><td>image evidence</td><td>not automatically the object source</td></tr><tr><td>Historical illustration</td><td>documentary record</td><td>record its source and date separately</td></tr></tbody></table><p><em>See the <a href="./intro.html">gallery overview</a>.</em></p>',8)])])}const g=a(o,[["render",d]]);export{p as __pageData,g as default};
